    RegistroAuditoria = apps.get_model('auditoria', 'RegistroAuditoria')

    for atencion in AtencionCiudadana.objects.filter(creado_por__isnull=True).iterator():
        auditorias = list(
            RegistroAuditoria.objects.filter(
                modelo='atenciones.AtencionCiudadana',
                objeto_id=str(atencion.pk),
                accion='crear',
            ).values_list('usuario_id', 'timestamp')
        )
        creadores = {usuario_id for usuario_id, _ in auditorias}
        if len(creadores) != 1 or None in creadores:
            continue
        if not any(
            abs((timestamp - atencion.fecha_registro).total_seconds()) <= 60
            for _, timestamp in auditorias
        ):
            continue
        atencion.creado_por_id = creadores.pop()
        atencion.save(update_fields=['creado_por'])


